<?php $title=ucfirst($role).' Dashboard';require dirname(__DIR__).'/views/layouts/header.php';$nav=['user'=>['Overview'=>'user/dashboard','My orders'=>'user/orders'],'admin'=>['Overview'=>'admin/dashboard','Event moderation'=>'admin/events'],'developer'=>['System overview'=>'developer/dashboard']];?><div class="dash-layout"><aside class="sidebar"><div class="eyebrow">WORKSPACE</div><div class="side-user"><div class="avatar"><?=e(strtoupper(substr(user()['name'],0,1)))?></div><div><b><?=e(user()['name'])?></b><small><?=e(strtoupper($role))?></small></div></div><?php foreach($nav[$role] as $label=>$href):?><a class="side-link <?=$path==='/'.$href?'active':''?>" href="<?=e(url($href))?>"><span>◈</span><?=e($label)?></a><?php endforeach;?><div class="side-note">Batavias<br><small>Plan. Manage. Experience.</small></div></aside><section class="dash-content"><div class="dash-title"><div><div class="eyebrow"><?=e(strtoupper($role))?> WORKSPACE</div><h1><?= $role==='user'?'Your event space':($role==='admin'?'Platform overview':'System overview') ?></h1><p class="muted">Welcome back, <?=e(user()['name'])?>.</p></div><span class="status-pill">● System operational</span></div><div class="stat-grid"><?php foreach($stats as $label=>$value):?><div class="stat-card"><span><?=e($label)?></span><strong><?=e(is_numeric($value)&&$label==='Revenue'?'Rp '.number_format((float)$value,0,',','.'):$value)?></strong><small>Live database value</small></div><?php endforeach;?></div><div class="panel table-panel"><div class="section-head"><h2><?= $role==='developer'?'Recent system activity':($role==='admin'?'Recent events':'Recent orders') ?></h2><?php if($role==='admin'):?><a class="text-link" href="<?=e(url('admin/events'))?>">Manage events →</a><?php elseif($role==='user'):?><a class="text-link" href="<?=e(url('user/orders'))?>">All orders →</a><?php endif;?></div><?php if($recent):?><div class="table-scroll"><table><thead><tr><?php foreach(array_keys($recent[0]) as $col):?><th><?=e(ucwords(str_replace('_',' ',$col)))?></th><?php endforeach;?></tr></thead><tbody><?php foreach($recent as $row):?><tr><?php foreach($row as $v):?><td><?=e($v)?></td><?php endforeach;?></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty">Belum ada aktivitas untuk ditampilkan.</div><?php endif;?></div><?php if($role==='developer'):?><div class="panel"><h2>API quick links</h2><p class="muted">Endpoint aktual yang tersedia:</p><code>GET <?=e(url('api/v1/health'))?></code><br><code>GET <?=e(url('api/v1/events'))?></code><br><code>GET <?=e(url('api/v1/me'))?></code></div><?php endif;?></section></div><?php require dirname(__DIR__).'/views/layouts/footer.php';?>